INSERT INTO about_me_entry (about_me_group_id, language_id, part, title, text) VALUES
(1, (SELECT language_id FROM language WHERE code = 'EN'), 1, 'About Me', 'Hello! I am a passionate developer always seeking new knowledge and challenges. After my studies and a journey through Southeast Asia, I am eager to build my professional career. I am highly motivated to grow and make a meaningful contribution to your company.'),
(1, (SELECT language_id FROM language WHERE code = 'EN'), 2, 'My Journey', 'My journey into software development began with a fascination for how technology shapes our world. I enjoy solving complex problems and creating efficient, scalable solutions.'),
(1, (SELECT language_id FROM language WHERE code = 'NL'), 1, 'Over Mij', 'Hallo! Ik ben een gepassioneerde ontwikkelaar die altijd op zoek is naar nieuwe kennis en uitdagingen. Na mijn studies en een reis door Zuidoost-Azië, ben ik enthousiast om mijn professionele carrière uit te bouwen. Ik ben zeer gemotiveerd om te groeien en een betekenisvolle bijdrage te leveren aan uw bedrijf.'),
(1, (SELECT language_id FROM language WHERE code = 'NL'), 2, 'Mijn Reis', 'Mijn reis in softwareontwikkeling begon met een fascinatie voor hoe technologie onze wereld vormgeeft. Ik geniet van het oplossen van complexe problemen en het creëren van efficiënte, schaalbare oplossingen.');